const data = $('Source 1').first().json;

// Initialize a map to group by date
const dailyData = new Map();

// Process each hourly record
for (let i = 0; i < data.hourly.time.length; i++) {
  const time = data.hourly.time[i];
  const date = time.substring(0, 10); // Extract YYYY-MM-DD

  if (!dailyData.has(date)) {
    dailyData.set(date, {
      date,
      hours: 0,
      pm2_5_max: -Infinity,
      pm10_max: -Infinity
    });
  }

  const record = dailyData.get(date);
  record.hours++;

  // Update max values
  if (data.hourly.pm2_5[i] > record.pm2_5_max) {
    record.pm2_5_max = data.hourly.pm2_5[i];
  }

  if (data.hourly.pm10[i] > record.pm10_max) {
    record.pm10_max = data.hourly.pm10[i];
  }
}

// Convert map values to array and remove Infinity placeholders
const records = Array.from(dailyData.values()).map(record => {
  if (record.pm2_5_max === -Infinity) record.pm2_5_max = null;
  if (record.pm10_max === -Infinity) record.pm10_max = null;
  return record;
});

return [{ json: { records } }];
